mapper.select:
-- @formatter:off
SELECT
-- 전체 학생 수
    (
        SELECT COUNT(DISTINCT s.student_id)
        FROM erp_student s
        WHERE s.status_key != 'WITHDRAWN'
        AND EXISTS (
        SELECT 1
        FROM erp_time_table_assign ta
        JOIN erp_time_table t ON ta.time_table_key = t.time_table_key
        WHERE ta.student_id = s.student_id
        AND t.center_code = #{centerCode}
        AND (#{roleKey} = 'ADMIN' OR t.user_code = #{userCode})
        AND t.yy = #{year}
        AND t.mm = #{month}
        )
        ) AS totalCount,

-- 이번달 입회
     (
SELECT COUNT(DISTINCT ta.student_id)
FROM erp_teacher_assign ta
WHERE (
    (#{roleKey} = 'ADMIN' OR ta.assign_han_teacher = #{userCode})
  AND SUBSTRING(CONVERT(VARCHAR, ta.entry_han_date, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, ta.entry_han_date, 120), 6, 2) = #{month}
    )
   OR (
    (#{roleKey} = 'ADMIN' OR ta.assign_book_teacher = #{userCode})
  AND SUBSTRING(CONVERT(VARCHAR, ta.entry_book_date, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, ta.entry_book_date, 120), 6, 2) = #{month}
    )
    ) AS entryCount,

-- 이번달 탈퇴
    (
SELECT COUNT(DISTINCT ta.student_id)
FROM erp_teacher_assign ta
WHERE (
    (#{roleKey} = 'ADMIN' OR ta.assign_han_teacher = #{userCode})
  AND SUBSTRING(CONVERT(VARCHAR, ta.inactive_han_date, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, ta.inactive_han_date, 120), 6, 2) = #{month}
    )
   OR (
    (#{roleKey} = 'ADMIN' OR ta.assign_book_teacher = #{userCode})
  AND SUBSTRING(CONVERT(VARCHAR, ta.inactive_book_date, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, ta.inactive_book_date, 120), 6, 2) = #{month}
    )
    ) AS withdrawCount,

-- 이번달 전입
    (
SELECT COUNT(*)
FROM erp_student_transfer_history
WHERE (#{roleKey} = 'ADMIN' OR to_user_code = #{userCode})
  AND center_code = #{centerCode}
  AND SUBSTRING(CONVERT(VARCHAR, move_at, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, move_at, 120), 6, 2) = #{month}
    ) AS transferInCount,

-- 이번달 전출
    (
SELECT COUNT(*)
FROM erp_student_transfer_history
WHERE (#{roleKey} = 'ADMIN' OR from_user_code = #{userCode})
  AND center_code = #{centerCode}
  AND SUBSTRING(CONVERT(VARCHAR, move_at, 120), 1, 4) = #{year}
  AND SUBSTRING(CONVERT(VARCHAR, move_at, 120), 6, 2) = #{month}
    ) AS transferOutCount
-- @formatter:on

select count(*)
from erp_student s
         join erp_parent p on s.student_id = p.student_id
where s.student_name = #{studentName}
  AND p.parent_tel_middle = #{parentTelMiddle}
  AND p.parent_tel_last = #{parentTelLast}

SELECT *
FROM erp_student_attendance
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}
ORDER BY attendance_date ASC

SELECT *
FROM erp_invite_tracking
WHERE invite_code = #{inviteCode}

