mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM erp_student
WHERE app_id = #{appId}
  AND student_id != #{studentId}

SELECT cc.class_key, cc.class_name, ecfm.fee
FROM erp_class_code cc
         JOIN erp_class_fee_map_copy ecfm ON cc.class_key = ecfm.class_key AND ecfm.center_code = #{centerCode}
         JOIN erp_student s ON s.student_id = #{studentId}
WHERE cc.class_type = '1'
  AND ((s.is_hoho = 1 AND ecfm.category = 'hoho') OR (s.is_hoho = 0 AND ecfm.category IN ('han', 'book')))

SELECT cc.class_key, cc.class_name, ecfm.fee
FROM erp_class_code cc
         JOIN erp_class_fee_map_copy ecfm ON cc.class_key = ecfm.class_key AND ecfm.center_code = #{centerCode}
         JOIN erp_student s ON s.student_id = #{studentId}
WHERE cc.class_type = '2'
  AND ((s.is_hoho = 1 AND ecfm.category = 'hoho') OR (s.is_hoho = 0 AND ecfm.category IN ('han', 'book')))

