SELECT *
FROM erp_teacher_assign
WHERE student_id = #{studentId}

SELECT CASE WHEN COUNT(1) > 1 THEN 1 ELSE 0 END
FROM erp_student_transfer_schedule
WHERE student_id = #{studentId}
  AND from_user = #{fromUserCode}
  AND status = 'SCHEDULED'

SELECT s.student_id AS studentId, sth.TRANSFER_NO as historyNo, sth.MOVE_AT as moveAt, s.STUDENT_NAME as studentName, c.CLASS_NAME as className, u1.USERNAME as fromTeacher, u2.USERNAME as toTeacher, sth.TRANSFER_REASON as transferReason, sth.CREATED_AT as createdAt
FROM STUDENT_TRANSFER_HISTORY sth JOIN class_code c ON sth.class_no = c.class_no JOIN user_tb u1 ON sth.from_user_no = u1.user_no JOIN user_tb u2 ON sth.to_user_no = u2.user_no JOIN student_tb s ON sth.student_no = s.student_no JOIN grade_code g ON s.grade_no = g.grade_no
s.student_no = #{studentId}

SELECT *
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 student_id as studentId
FROM erp_change_app_id
WHERE old_app_id = #{appId}

SELECT COUNT(in_time)
FROM erp_student_attendance
WHERE student_id = #{studentId}
  and attendance_date = #{attendanceDate}

SELECT COUNT(*)
FROM erp_student_attendance
WHERE student_id = #{studentId}
  AND attendance_date = #{ymd}
  AND time_table_key = #{timeTableKey}

SELECT week, year AS yy, month AS mm
FROM erp_class_week
WHERE center_code = #{centerCode}
  AND (
    mon = #{absenceDate}
   OR tue = #{absenceDate}
   OR wed = #{absenceDate}
   OR
    thu = #{absenceDate}
   OR fri = #{absenceDate}
   OR sat = #{absenceDate}
   OR sun = #{absenceDate}
    )

mapper.update:
UPDATE erp_student_attendance
SET in_time             = #{inTime},
    out_time            = null,
    attendance_date     = CAST(SYSDATETIME() AS DATE),
    attendance_key      = #{attendanceKey},
    check_in_updated_at = SYSDATETIME()
WHERE student_id = #{studentId}
  AND week = #{week}
  AND yy = #{yy}
  AND mm = #{mm}
  AND time_table_key = #{timeTableKey}
  AND (in_time IS NULL OR in_time = '')

UPDATE erp_remedial
SET in_time        = #{inTime},
    attendance_key = #{attendanceKey}
WHERE remedial_key = #{remedialKey}
  AND (in_time IS NULL OR in_time = '')

UPDATE erp_remedial
SET out_time = #{outTime}
WHERE remedial_key = #{remedialKey}
  AND in_time IS NOT NULL
  AND (out_time IS NULL OR out_time = '')

UPDATE erp_student_attendance
SET is_remedial = 1
WHERE student_id = #{studentId}
  AND time_table_key = #{timeTableKey}
  AND week = #{week}
  AND yy = #{yy}
  AND mm = #{mm}

