SELECT COUNT(1) > 0
FROM student_monthly_snapshot
WHERE snapshot_ym = #{ym}

mapper.insert:
DELETE FROM student_monthly_snapshot WHERE snapshot_ym = #{ym};
INSERT INTO student_monthly_snapshot (snapshot_ym, active_count, rest_count, withdrawn_count, wait_count, created_at)
SELECT #{ym}, SUM(CASE WHEN sc.status = '재원중' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '휴원' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '탈퇴' THEN 1 ELSE 0 END), SUM(CASE WHEN sc.status = '입학취소' THEN 1 ELSE 0 END), CURRENT_TIMESTAMP
FROM student_tb s JOIN status_code sc ON s.status_no = sc.status_no;

mapper.select:
SELECT CASE WHEN sa.student_id IN ('DAE0012603262D574', 'DAE001260326C1369', 'DAE001260326C1369', 'DAE001260326902E7', 'DAE0012604028231B', 'DAE0012604026A01C') AND #{mm} = '04' THEN CASE t.dayname WHEN 'mon' THEN CAST(DATEADD(DAY, -7, ecw.mon) AS DATE) WHEN 'tue' THEN CAST(DATEADD(DAY, -7, ecw.tue) AS DATE) WHEN 'wed' THEN CAST(DATEADD(DAY, -7, ecw.wed) AS DATE) WHEN 'thu' THEN CAST(DATEADD(DAY, -7, ecw.thu) AS DATE) WHEN 'fri' THEN CAST(DATEADD(DAY, -7, ecw.fri) AS DATE) WHEN 'sat' THEN CAST(DATEADD(DAY, -7, ecw.sat) AS DATE) WHEN 'sun' THEN CAST(DATEADD(DAY, -7, ecw.sun) AS DATE) END ELSE CASE t.dayname WHEN 'mon' THEN ecw.mon WHEN 'tue' THEN ecw.tue WHEN 'wed' THEN ecw.wed WHEN 'thu' THEN ecw.thu WHEN 'fri' THEN ecw.fri WHEN 'sat' THEN ecw.sat WHEN 'sun' THEN ecw.sun END END AS ymd, t.dayname, ISNULL(sa.in_time, '') AS stime, ISNULL(sa.out_time, '') AS etime, t.start_time AS plannedStime, t.end_time AS plannedEtime, sa.week, '수업' AS gb FROM erp_student_attendance sa JOIN erp_time_table t ON t.time_table_key = sa.time_table_key JOIN erp_student s ON sa.student_id = s.student_id JOIN erp_class_week ecw ON ecw.week = sa.week AND ecw.center_code = s.center_code AND ecw.year = #{yy} AND ecw.month = #{mm} WHERE sa.student_id = #{studentId} AND sa.yy = #{yy} AND sa.mm = #{mm}
UNION ALL
SELECT r.remedial_date AS ymd, t.dayname, ISNULL(r.in_time, '') AS stime, ISNULL(r.out_time, '') AS etime, r.s_time AS plannedStime, t.end_time AS plannedEtime, r.week, '보강' AS gb FROM erp_remedial r JOIN erp_time_table t ON t.time_table_key = r.time_table_key WHERE r.student_id = #{studentId} AND r.yy = #{yy} AND r.mm = #{mm}
ORDER BY ymd

SELECT sibling_key as siblingKey
